import collections

def lining_up(arr):
    count = collections.Counter(arr)
    result = 1
    if len(arr) % 2 == 0:
        must_contain = set([num for num in range(1, len(arr), 2)])
        for offset in count:
            if count[offset] != 2 or offset not in must_contain:
                return 0
        for num in must_contain:
            if num not in count:
                return 0
    else:
        must_contain = set([num for num in range(2, len(arr), 2)])
        if 0 not in count or count[0] != 1:
            return 0
        for offset in count:
            if offset != 0 and (count[offset] != 2 or offset not in must_contain):
                return 0
        for num in must_contain:
            if num not in count:
                return 0

    return (2 ** (len(arr) // 2)) % (10 ** 9 + 7)

