mod=10**9+7
n=int(input())
A=tuple(map(int,input().split()))

def solve(n,A):
    D=defaultdict(int)
    for a in A:
        D[a]+=1
    if n%2:
        if D[0]!=1:
            return 0
        for i in range(2,n,2):
            if D[i]!=2:
                return 0
    else:
        for i in range(1,n,2):
            if D[i]!=2:
                return 0
    return pow(2,n//2,mod)

