def judge(A):
    count = [0] * len(A)
    for i in range(len(A)):
        count[A[i]] += 1
    if len(A) & 1 == 0:
        for j in range(len(A)//2):
            if count[j*2+1] != 2:
                return False
        return True
    else:
        for j in range((len(A)-1)//2):
            if j == 0:
                if count[0] != 1:
                    return False
            else:
                if count[j*2] != 2:
                    return False
        return True


