from typing import Optional


def get_str(s: str, ind: int) -> Optional[str]:
    return s[ind] if 0 <= ind < len(s) else None


def compute(s: str) -> bool:
    while len(s) > 0:
        if s.startswith('dream') and get_str(s, 5) != 'e':
            s = s[len('dream'):]
        elif s.startswith('dreamer') and get_str(s, 7) != 'a':
            s = s[len('dreamer'):]
        elif s.startswith('dreamera'):
            s = s[len('dream'):]
        elif s.startswith('eraser'):
            s = s[len('eraser'):]
        elif s.startswith('erase'):
            s = s[len('erase'):]
        else:
            return False

    return True


def main() -> None:
    s = input()
    ok = compute(s)

    if ok:
        print('YES')
    else:
        print('NO')


