def cumulative_sum(l, x, y):  # list in x to y and x < y
    return sum(l[:y]) - sum(l[:x])


def two_dimension_gen(x, y):
    l = np.zeros((x, y))
    return l


def str_to_int_sort(str_, x):  # 0 = normal, 1 = reverse. unaccept alphabet
    if x == 0:
        st = sorted(str_)
        st = ''.join(map(str, st))
        return int(st)
    elif x == 1:
        st = list(str_)
        st.sort(reverse=True)
        st = ''.join(map(str, st))
        return int(st)
    else:
        print(-1)


def make_divisors(x):
    l_div, u_div = [], []
    i = 1
    while i * i <= x:
        if x % i == 0:
            l_div.append(i)
            if i != x // i:
                u_div.append((x // 1))
        i += 1
    return l_div + u_div[::-1]


def dup_list_d(l):
    l1 = l.copy()
    ret = [None] * (len(l) + len(l1))
    ret[::2] = l
    ret[1::2] = l1
    return ret


def div_list_d(l):
    x, y = [], []
    x = l[::2]
    y = l[1::2]
    return x, y


def reverse(S):
    X = []
    str = ""
    for i in range(len(S)):
        i += 1
        X.append(S[-i])

    return str.join(X)


def permutation(l):
    return list(it.permutations(l))


def combination(l, p):
    return list(it.combinations(l, p))


