def factorization(n) -> dict:
    '''
    素因数分解する．
    '''
    dict_ = {}
    for i in range(2, floor(n**0.5)+1):
        if n % i == 0:
            cnt = 0
            while n % i == 0:
                cnt += 1
                n //= i
            dict_[i] = cnt
    if n != 1:
        dict_[n] = 1
