def compress(arr: list) -> list:
    return {v: i for i, v in enumerate(sorted(set(arr)))}


def SPF(n: int) -> list:
    '''
    nまでの自然数についてSPF(Smallest Prime Factor; 最小の素因数)を返す
    '''
    table = [inf]*(n+1)
    for i in range(2, n+1):
        if table[i] != inf:
            continue
        idx = i
        while idx <= n:
            table[idx] = min(table[idx], i)
            idx += i
    return table


def factorization_with_SPF(n: int) -> defaultdict:
    '''
    SPFを用いた素因数分解．
    計算量O(log(n))
    '''
    ret = defaultdict(int)
    while n > 1:
        _spf = SPF[n]
        ret[SPF[n]] += 1
        n //= _spf
    return ret


def sum_of_arithmetic_sequence(a, d, n):
    return (a*2+(n-1)*d)*n//2


def sum_of_1_to_n(n):
    return n*(n+1)//2


