"""
https://atcoder.jp/contests/abc177/editorial/82

https://atcoder.jp/contests/abc052/tasks/arc067_a

学んだこと
・素因数分解をMlogMで実施できる。
前計算としてエラトステネスの篩を行い、「その数をふるい落とした素数」を配列 D に記録します。
例えば D[4]=D[6]=2,D[35]=5 です。x が素数のときは D[x]=x としておきます。
この配列はエラトステネスの篩と同様O(AloglogA) で構築できます。
D[x] は x を割り切る最小の素数なので、この配列 D を利用すると素因数分解を行うときに「試し割り」を
する必要がなくなり(D[x]で割ればよい)、1つの数の素因数分解が素因数の個数である O(logA) でできるようになります。
"""

import sys
input = sys.stdin.readline
from collections import defaultdict
from operator import itemgetter, truediv
def II(): return int(input())
def IS(): return input().rstrip()
def MI(): return map(int, input().split())
def LI(): return list(map(int, input().split()))
def MS(): return input().rstrip().split()
def LS(): return list(input().rstrip())
from math import gcd

# 「その数をふるい落とした素数」を配列 d に記録する
def eratosthenes(n):
    if n < 2:
        return [1]*(n+1)
    d = [1]*(n+1)
    num_set=set() # 素数pによって合成される数のセット
    for i in range(2, n+1):
        if i not in num_set:
            d[i] = i
            """
            i^2からスタートして良い理由は、『iが２から始まっているから』。
            例えば2の倍数をチェックし終えたら、次は３の倍数を確認するが、
            3*2 (i*(i-1))という組み合わせは確認する必要がありません。
            なぜならば、2*3(i*(i+1))のパターンをチェックしているから。
            """
            for j in range(i*i, n+1, i):
                num_set.add(j)
                d[j] = i
    return d

# nの素因数分解をO(logn)で実施する。
# 事前に、想定される最大の数までで、「その数をふるい落とした素数」を
# 記録する配列lを用意する。こちらはO(MlogM)で対応可能（Mはnの最大値)
def super_factorization(n:int,l:list,d:defaultdict(int)):
    if n == 1:
        d[1] = 1
    while n != 1:
        d[l[n]] += 1
        n //= l[n]

def solve():
    n = II()
    d = defaultdict(int)
    l = eratosthenes(n)
    for i in range(1,n+1):
        super_factorization(i,l,d)
    s = 1
    for cnt in d.keys():
        if cnt == 1:
            continue
        s *= (d[cnt]+1)
        s %= (10**9+7)
    print(s)
if __name__ == '__main__':
    solve()

