def Erathosthenes(n):
    primes = []
    is_prime = [True for _ in range(n + 1)]

    for i in range(2, int(n ** 0.5) + 1):
        if not is_prime[i]: continue
        j = i * 2
        while j <= n:
            is_prime[j] = False
            j += i

    for i in range(2, n + 1):
        if is_prime[i]:
            primes.append(i)

    return primes

