def factorization(n):
    d = defaultdict(int)
    cnt = 0
    tmp = n
    i = 2
    while i * i <= n:
        if tmp % i == 0:
            cnt = 0
            while tmp % i == 0:
                cnt += 1
                tmp /= i
            d[i] = cnt
        i += 1
    if tmp != 1:
        d[tmp] = 1
    if len(d) == 0:
        d[n] = 1
    return d

