import math


def prime_factors(x):
    MAX = int(math.sqrt(x))
    C = [0] * (MAX + 1)
    for i in range(2, MAX + 1):
        while x % i == 0:
            x //= i
            C[i] += 1
    res = [(i, c) for i, c in enumerate(C) if c > 0]
    if x != 1:
        res.append((x, 1))
    return res


