import sys
from collections import defaultdict

def sieve(n):
    """Sieve of Eratosthenes"""
    if n < 2:
        is_prime = [False for _ in range(n+1)]
        return is_prime

    is_prime = [True for _ in range(n+1)]
    is_prime[0] = False
    is_prime[1] = False

    for i in range(2, int(n**0.5)+1):
        if is_prime[i]:
            for j in range(i*2, n+1, i):
                is_prime[j] = False

    prime = []
    for i in range(n+1):
        if is_prime[i]:
            prime.append(i)

    return prime


def main():
    input = sys.stdin.readline
    N = int(input())
    MOD = 10**9 + 7

    if N == 1:
        return 1

    prime = sieve(N)
    d = defaultdict(lambda: 0)
    for i in range(2, N+1):
        m = i
        for p in prime:
            if p > m:
                break

            while m % p == 0:
                d[p] += 1
                m //= p

    ans = 1
    for key in d.keys():
        ans *= d[key] + 1

    return ans % MOD


