def main():
    n, m = inputs()
    from itertools import product

    a = [None] * n
    for i in range(n):
        a[i] = list(input_(str))

    b = [None] * m
    for i in range(m):
        b[i] = list(input_(str))

    # print(a)
    # print(b)

    def match(sy, sx):
        for i, j in product(range(m), repeat=2):
            if a[sy + i][sx + j] != b[i][j]:
                return False

        return True

    for y, x in product(range(n - m + 1), repeat=2):
        if match(y, x):
            print('Yes')
            exit()

    print('No')


