def count_path(s, no, visit, adj, n_node):   # 点sに no番目に到着したときのパス数を返す
    if no == n_node:
        return 1

    visit[s] = no
    ret = 0
    for e in adj[s]:
        if visit[e] == 0:
            ret += count_path(e, no+1, visit, adj, n_node)
    visit[s] = 0
    return ret


