    a, b = map(int, input().split())
    node_dict[a].add_node(node_dict[b])
    node_dict[b].add_node(node_dict[a])

def count_permutation(now_node, remain_node_dict):
    count = 0
    if len(remain_node_dict) == 0:
        return 1
    else:
        for index in remain_node_dict.keys():
            next_remain_node_dict = deepcopy(remain_node_dict)
            next_node = next_remain_node_dict.pop(index)
            if now_node.rinsetsu.get(next_node.index, None) is not None:
                count += count_permutation(next_node, next_remain_node_dict)

        return count

