def base10to(n, b): #10-> b
    if (int(n/b)):
        return base10to(int(n/b), b) + str(n%b)
    return str(n%b)

def base10from(num, b): #b -> 10
    n = 0
    numlist = list(num)
    while (numlist):
        n *= b
        n += int(numlist.pop(0))
    return n

def base8_to_10(base8):
    x = 1

    ret = 0
    for i in reversed(range(0, len(base8))):
        ret += int(base8[i]) * x
        x *= 8

    return ret

def base10_to_9(base10):
    if base10 == 0:
        return "0"
    ret = ""
    while base10 > 0:
        s = base10 % 9
        ret = str(s) + ret
        base10 = base10 // 9
    return ret

def base10_to_2(base10):
    if base10 == 0:
        return "0"
    ret = ""
    while base10 > 0:
        s = base10 % 2
        ret = str(s) + ret
        base10 = base10 // 2
    return ret

def combinations_count(n, r):
    return math.factorial(n) // (math.factorial(n - r) * math.factorial(r))

