import sys
from itertools import permutations


def solve(N: int, M: int, a: "List[int]", b: "List[int]"):
    edges = set()
    for m in range(M):
        c, d = a[m], b[m]
        edges.add((c, d))

    permutation_list = [list(x) for x in permutations(range(2,N+1))]
    count = 0
    for permutation in permutation_list:
        a = 1
        visited = [1]
        while permutation:
            b = permutation.pop()
            if b in visited:
                break

            if (a, b) not in edges and (b, a) not in edges:
                break

            a = b
            visited.append(b)

        if len(visited) ==N:
            count += 1

    print(count)
    return


