def next(root_idx, edges, histories, node_num):
  #print(root_idx, edges, histories, node_num)
  count = 0
  if root_idx not in edges:
    return count
  nexts = edges[root_idx]
  if len(histories) + 1 == node_num:
    return len(set(nexts) - set(histories))
  #print('nexts: ' + ','.join(map(str, nexts)))
  for next_idx in nexts:
    if next_idx in histories:
      continue
    count += next(next_idx, edges, histories + [next_idx], node_num)
  return count

