                if S & (1 << v):
                    continue
                if (0, v) in edge or (v, 0) in edge:
                    dp[S | (1 << v)][v] += dp[S][0]
        else:
            for u in range(1, n):
                if not (S & (1 << u)):
                    continue
                for v in range(n):
                    if S & (1 << v):
                        continue
                    if (u, v) in edge or (v, u) in edge:
                        dp[S | (1 << v)][v] += dp[S][u]
    print(sum(dp[-1]))


