def dfs(v, graph, visited, c, ans, n):
    if c == n:
        ans += 1
        return ans

    for i in graph[v]:
        if not visited[i]:
            visited[i]= True
            ans = dfs(i, graph, visited, c + 1, ans, n)
            visited[i] = False
    return ans


