def search(N,adj):
    visited={1:[1]}
    S=[[1]]
    paths=[]
    while len(S)!=0:
        p=S.pop()
        if len(p)==N:
            paths.append(p)
        else:
            for w in adj[p[-1]]:
                if w not in p:
                    S.append(p+[w])
    return paths


