import sys


def solve(K, S):
    ans = 0
    for x in range(K+1):
        for y in range(K+1):
            z = S - x - y
            if 0 <= z <= K:
                ans += 1
            elif z < 0:
                break
    return ans


def main(args):
    K, S = map(int, input().split())
    ans = solve(K, S)
    print(ans)


