class SumofThreeIntegers:
    def calculate(self, K, S):
        self.counter = 0
        for x in range(K+1):
            for y in range(K+1):
                z = S - x - y
                if z < 0 or K < z:
                    pass
                elif x + y + z == S:
                    self.counter += 1
        return self.counter

