def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, X, A):
    ans = 0
    for i, a in enumerate(A):
        ans += max(0, a-X)
        A[i] = min(a, X)

    for i in range(1, N):
        if A[i-1] + A[i] > X:
            ans -= X - (A[i-1] + A[i])
            A[i] += X - (A[i-1] + A[i])
    return ans


