# 各桁の値リスト（k進数のとき）
def digit_val(n, k):
    ans = []
    while n != 0:
        ans.append(n % k)
        n //= k
    return ans

# 最大公約数
def my_gcd(a, b):
    return math.gcd(a, b)

# 最小公倍数
def my_lcm(a, b):
    return (a * b) // my_gcd(a, b)

