import sys

def iterate_tokens():
    for line in sys.stdin:
        for word in line.split():
            yield word


def solve(N: int, x: int):
    tokens = iterate_tokens()
    a = int(next(tokens))
    s = 0
    for _ in range(N-1):
        new = int(next(tokens))
        if a + new > x:
            s += a + new - x
            new -= min(new, a + new - x)
        a = new
    print(s)
    return


