def factorization(n):
    arr = []
    temp = n
    for i in range(2, int(-(-n**0.5//1))+1):
        if temp % i == 0:
            cnt = 0
            while temp % i == 0:
                cnt += 1
                temp //= i
            arr.append([i, cnt])

    if temp != 1:
        arr.append([temp, 1])

    if arr == []:
        arr.append([n, 1])

    return arr


def factorize_list_format_change(fact_list_old):
    fact_list_new = []
    for prime_num in fact_list_old:
        for _ in range(prime_num[1]):
            fact_list_new.append(prime_num[0])
    return fact_list_new


def calc_degit(num):
    return len(str(num))

