        for j in range(len(fact_list)):
            if grouping_str[j] == "0":
                A *= fact_list[j]
            else:
                B *= fact_list[j]
        min_F_temp = max(calc_degit(A), calc_degit(B))
        if(min_F_temp < min_F):
            min_F = min_F_temp
    print(min_F)


