class Solver:
    def input(self):
        """
        faster input function than builtin stdin.
        """
        return sys.stdin.readline()[:-1]

    def ii(self, t: type = int):
        """
        input single value.
        """
        return t(self.input())

    def il(self, t: type = int):
        """
        input single line.
        """
        return list(map(t, self.input().split()))

    def imi(self, N: int, t: type = int):
        """
        input multi value.
        """
        return [self.ii(t) for _ in range(N)]

    def iml(self, N: int, t: type = int):
        """
        input multi line.
        """
        return [self.il(t) for _ in range(N)]

    def solve(self):
        N, M = self.il()
        AB = self.iml(N)
        CD = self.iml(M)
        for i in range(N):
            d = float("inf")
            for j in range(M):
                dd = abs(AB[i][0] - CD[j][0]) + abs(AB[i][1] - CD[j][1])
                if d > dd:
                    ans = j + 1
                d = min(d, dd)
            print(ans)


