    student_points = []
    checkpoint_list = []

    for _ in range(n_students):
        a, b = input_int_map()
        student_points.append((a, b))

    for _ in range(m_checkpoint):
        c, d = input_int_map()
        checkpoint_list.append((c, d))

    for student_point in student_points:

        near_checkpoint_i = -1
        min_checkpoint_kyori = float('inf')

        for checkpoint_i in range(m_checkpoint):
            kyori = get_kyori(student_point, checkpoint_list[checkpoint_i])

            if kyori < min_checkpoint_kyori:
                near_checkpoint_i = checkpoint_i
                min_checkpoint_kyori = kyori

        print(near_checkpoint_i + 1)


def get_kyori(student_point, checkpoint) -> int:
    return abs(student_point[0] - checkpoint[0]) + abs(student_point[1] - checkpoint[1])


