def resolve():
    from collections import deque
    n = int(input())
    d = deque()
    A = list(map(int, input().split()))

    reverse = False
    for i in range(n):
        if not reverse:
            d.append(A[i])
            reverse = not reverse
        else:
            d.appendleft(A[i])
            reverse = not reverse

    if not reverse:
        for i in d:
            print(i, end=' ')
    else:
        for i in reversed(d):
            print(i, end=' ')


resolve()

