    ans = pushpush(N, A)
    print(' '.join(map(str, ans)))

def c_pushpush(N, A):
    from collections import deque
    ans = deque([])  # リストの先頭への挿入はO(要素数)なので
    n_parity = N & 1
    for i, a in enumerate(A, 1):
        if n_parity == i & 1:
            ans.appendleft(a)
        else:
            ans.append(a)
    return ' '.join(map(str, ans))

