import collections


def solve_abc066c(n, A):
    q = collections.deque()

    is_reversed = False

    for i in range(n):
        a = A[i]

        if not is_reversed:
            q.append(a)
        else:
            q.appendleft(a)

        is_reversed = not is_reversed

    if is_reversed:
        q = reversed(q)

    return ' '.join(map(str, q))


