import sys
from collections import deque

def solve(n: int, a: "List[int]"):
    inv = False
    b = deque()
    for aa in a:
        if not inv:
            b.append(aa)
            inv ^= 1
        else:
            b.appendleft(aa)
            inv ^= 1
    b = list(b)
    if not inv:
        print(*b, sep=" ")
    else:
        print(*b[::-1], sep=" ")
    return


