def is_same_sign(a, b):
    if a < 0 and b < 0:
        return True
    elif a > 0 and b > 0:
        return True
    return False


def calc(n, s, c):
    pre_total = s[0]
    for i in range(1, n):
        total = pre_total + s[i]
        # print(S[i], pre_total, total, is_same_sign(pre_total, total))

        if total == 0:
            if pre_total < 0:
                c += 1
                total = 1
            else:
                c += 1
                total = -1

        elif is_same_sign(pre_total, total):
            if pre_total < 0:
                c += abs(total) + 1
                total = total + abs(total) + 1
            else:
                c += abs(total) + 1
                total = -1

        pre_total = total

    return c


def plus_first(n, s):
    c = 0

    # 先頭を正にする. 正なら何もしない
    if s[0] <= 0:
        c += abs(s[0]) + 1
        s[0] = 1

    res = calc(n, s, c)
    return res


def minus_first(n, s):
    c = 0

    # 先頭を負にする. 負なら何もしない
    if s[0] >= 0:
        c += abs(s[0]) + 1
        s[0] = -1

    res = calc(n, s, c)
    return res


