def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, A):
    S = [A[0]]
    for a in A[1:]:
        S.append(S[-1]+a)

    def f(sig):
        o = 0
        ans = 0
        for s in S:
            s += o
            if s == 0:
                ans += 1
                o -= sig
            elif sig * s > 0:
                ans += abs(s) + 1
                o -= sig*(abs(s) + 1)
            sig *= -1
        return ans

    return min(f(1), f(-1))


