def check(n,s,x):
    cnt=0
    f=0
    for i in range(n):
        if i%2==0:
            if (s[i]+f)*x<=0:
                cnt+=abs(x-s[i]-f)
                f+=x-s[i]-f
        else:
            if (s[i]+f)*x>=0:
                cnt+=abs(-x-s[i]-f)
                f+=-x-s[i]-f
    return cnt

