def main():
    n = int(sys.stdin.readline())

    max_a = -1
    min_a = 1001

    line = sys.stdin.readline()
    for ch in line.split():
        a = int(ch)
        if a > max_a:
            max_a = a
        if a < min_a:
            min_a = a

    print(max_a - min_a)
    return 0

if __name__ == '__main__':
    sys.exit(main())

