    [A, B, C] = list(map(lambda x: int(x), inputs[0].split()))
    first_state = A % B
    state = None
    if first_state == C:
        return "YES"

    sum = A
    while state != first_state:
        sum += A
        sur = sum % B
        if sur == C:
