def read_line(n=0):
    if n == 0:
        return input().rstrip()
    else:
        return input().rstrip()[:n]


def think(a, b, c):
    m_seed = a % b
    while m_seed >= b:
        m_seed %= b

    visited = set()
    m_accumulated = m_seed
    while True:
        if m_accumulated == c:
            return True
        if m_accumulated in visited:
            return False
        visited.add(m_accumulated)
        m_accumulated += m_seed
        while m_accumulated >= b:
            m_accumulated %= b


def write(result):
    if result:
        print('YES')
    else:
        print('NO')


