def one(X):
  L, R = 0, 0
  for x in X:
    if x == "(":
      R += 1
    else:
      if R == 0:
        L += 1
      else:
        R -= 1
  return L*"("+X+R*")"

def two(X):
  mL = 0
  for i in X:
    if i == ")":
      mL += 1
    else:
      break
  mR = 0
  for i in X[::-1]:
    if i == "(":
      mR += 1
    else:
      break
  X = mL * "(" + X + mR * ")"
  L = len([i for i in X if i == ")"])
  R = len(X) - L
  if L > R:
    X = (L - R) * "(" + X
  else:
    X += (R - L) * ")"
  return X

