class NumberTheory:
  class PrimeNumbers: # pn
    def __init__(self, n=2*10**6):
      self.is_prime, self.prime_nums = self.find(n)

    def __call__(self, n): return self.is_prime[n]
    def __iter__(self): return iter(self.prime_nums)
