    if m - n > 1: return 0
    d_combs: ModInt = reduce(mul, range(2, n+1), ModInt(1))
    m_combs: ModInt = reduce(mul, range(n+1, m+1), d_combs)

    return d_combs * m_combs * ((m == n) + 1)

if __name__ == '__main__':
    print(reconciled())

