from collections import Counter
from string import ascii_lowercase

def biggest(s):
    common = ''
    for c in ascii_lowercase:
        if all(map(lambda d: c in d, s)):
            occurrences = min(map(lambda d: d[c], s))
            common += c * occurrences
    return common


