    def t(self):
        arr = [self.arr[0]]*(len(self.arr))
        x = 0
        for i in range(self.n):
            for j in range(self.m):
                arr[j*self.n + i] = self.arr[x]
                x += 1
        return self.__init__(self.m, self.n, arr)


