def scc(graph, rgraph):
    n = graph.n_vertices
    order = []
    color = [0] * n
    for v0 in range(n):
        if color[v0]:
            continue
        color[v0] = -1
        stack = [iter(graph.adj(v0))]
        path = [v0]
        while path:
            for u in stack[-1]:
                if color[u] == 0:
                    color[u] = -1
                    path.append(u)
                    stack.append(iter(graph.adj(u)))
                    break
            else:
                v = path.pop()
                order.append(v)
                stack.pop()

    label = 0
    for v0 in reversed(order):
        if color[v0] >= 0:
            continue
        color[v0] = label
        stack = [v0]
        while stack:
            v = stack.pop()
            for u in rgraph.adj(v):
                if color[u] < 0:
                    color[u] = label
                    stack.append(u)
        label += 1
    return label, color


