def chmin(v, dp, idx):
  if v < dp[idx]:
    dp[idx] = v
    return True
  return False


def search(graph: List[List[Edge]], N: int, start: int):
  neg_cyc = False

  dist = [inf] * N
  dist[start] = 0

  for i in range(2 * N + 1):
    update = False
    for v in range(N):
      if dist[v] == inf:
        continue

      for e in graph[v]:
        if chmin(dist[v] + e.weight, dist, e.to):
          update = True
          if e.to == N - 1 and i == 2 * N:
            neg_cyc = True
    if not update:
      break

  return neg_cyc, -dist[-1]


def main():
  neg_cyc, last_dist = search(graph, N, 0)
  if neg_cyc:
    return "inf"
  else:
