def Bellman_Ford(D,From,To):
    """Bellman_Ford法を用いて, FromからToまでの距離を求める. (負閉路が存在する場合, 返り値は-inf)

    D:有向グラフ
    """

    inf=float("inf")
    T={v:inf for v in D.vertex}
    T[From]=0

    N=len(D.vertex)

    E=[]
    for u in D.vertex:
        F=D.adjacent_out[u]
        for v in D.vertex:
            if v in F:
                E.append((u,v,F[v]))

    for k in range(N):
        update=0
        for u,v,c in E:
            if T[v]>T[u]+c:
                T[v]=T[u]+c
                update=1

        if not update:
            return T[To]

    X={v:1 for v in D.vertex}
    for u,v,c in E:
        if T[v]>T[u]+c:
            T[v]=T[u]+c
            X[v]=0

    return T[To] if X[To] else -inf
