def bellman_ford(s, g):
    n = len(g)
    dist = [INF] * n
    dist[s] = 0
    for i in range(n):
        for v, e in enumerate(g):
            for cost, t in e:
                if dist[v] != INF and dist[v] + cost < dist[t]:
                    dist[t] = dist[v] + cost
                    if i == n - 1:
                        dist[t] = -INF
    return dist

