        stack = [i]; visited[i] = True
        while stack:
          u, cnt = stack[-1], 0
          for v, e in self.edges[u].items():
            if visited[v]: continue
            visited[v] = True; stack.append(v); cnt += 1
          if not cnt: order[u] = j; j += 1; stack.pop()

      gg = self.__class__(n)
      root, j = [None]*n, 0
      for u in range(n):
        for v, e in self.edges[u].items(): gg.add_edge(v, u)
      for i, _ in sorted(enumerate(order), key=lambda x: -x[1]):
        if root[i] is not None: continue
        stack = [i]; root[i] = j
        while stack:
          u = stack.pop()
          for v, e in gg.edges[u].items():
            if root[v] is not None: continue
            root[v] = j; stack.append(v)
        j += 1
      return root



  @staticmethod
  def triangle_area(p0, p1, p2, signed=False):
    x1, y1, x2, y2 = p1[0]-p0[0], p1[1]-p0[1], p2[0]-p0[0], p2[1]-p0[1]
    return (x1*y2 - x2*y1)/2 if signed else abs(x1*y2 - x2*y1)/2 

  @classmethod
  def intersect(cls, seg1, seg2):
    (p1, p2), (p3, p4) = seg1, seg2
    t1 = cls.triangle_area(p1, p2, p3, signed=True)
    t2 = cls.triangle_area(p1, p2, p4, signed=True)
    t3 = cls.triangle_area(p3, p4, p1, signed=True)
    t4 = cls.triangle_area(p3, p4, p2, signed=True)
    return (t1*t2<0) & (t3*t4<0)


