    inf = float('inf')
    dj = [-inf] * (n + 1)
    dj[st] = 0
    for _ in range(N):
        updated = False
        for link in links:
            fn, tn, lc = link
            if dj[fn] + lc > dj[tn]:
                dj[tn] = dj[fn] + lc
                updated = True
        if not updated: break
    else:
        negative = [False] * (n + 1)
        for _ in range(N):
            for link in links:
                fn, tn, lc = link
                negative[tn] |= negative[fn]
                if dj[fn] + lc > dj[tn]:
                    dj[tn] = dj[fn] + lc
                    negative[tn] = True
        if negative[N]: return inf
    return dj[-1]

