      self.parent[u] = self.find(self.parent[u])
      return self.parent[u]

    def unite(self, u, v):
      u, v = self.find(u), self.find(v)
      if u == v: return 
      if self.rank[u] < self.rank[v]: u,v = v,u
      self.parent[v] = u 
      self.size[u] += self.size[v]
      self.rank[u] = max(self.rank[u], self.rank[v]+1)

