def umeru(zu, x, y, a):
    for Y, row in enumerate(zu):
        for X, v in enumerate(row):
            if a == 1:
                if X < x:
                    zu[Y][X] = 1
            if a == 2:
                if X > x - 1:
                    zu[Y][X] = 1
            if a == 3:
                if Y < y:
                    zu[Y][X] = 1
            if a == 4:
                if Y > y - 1:
                    zu[Y][X] = 1


