    G = [[1] * W for _ in range(H)]

    for _ in range(N):
        x, y, a = map(int, readline().split())
        if a == 1:
            for col in range(x):
                for row in range(H):
                    G[row][col] = 0
        elif a == 2:
            for col in range(x, W):
                for row in range(H):
                    G[row][col] = 0
        elif a == 3:
            for row in range(y):
                for col in range(W):
                    G[row][col] = 0
        else:
            for row in range(y, H):
                for col in range(W):
                    G[row][col] = 0

    ans = 0
    for r in G:
        ans += sum(r)
    print(ans)


