def str_to_int_sort(str_, x):  # 0 = normal, 1 = reverse. unaccept alphabet
    if x == 0:
        st = sorted(str_)
        st = ''.join(map(str, st))
        return int(st)
    elif x == 1:
        st = list(str_)
        st.sort(reverse=True)
        st = ''.join(map(str, st))
        return int(st)
    else:
        print(-1)


def make_divisors(x):
    l_div, u_div = [], []
    i = 1
    while i * i <= x:
        if x % i == 0:
            l_div.append(i)
            if i != x // i:
                u_div.append((x // 1))
        i += 1
    return l_div + u_div[::-1]


