def a():
    N = int(input())
    X, Y = [], []

    for v in range(N):
        x, y = map(int, input().split())
        X.append((x, v))
        Y.append((y, v))

    X.sort()
    Y.sort()

    E = []
    for i in range(N):
        for j in range(max(0, i - 1), min(N - 1, i + 1)):
            if i == j:
                continue
            x1, v1 = X[i]
            x2, v2 = X[j]
            E.append((abs(x2 - x1), v1, v2))

            y1, v1 = Y[i]
            y2, v2 = Y[j]
            E.append((abs(y2 - y1), v1, v2))
    E.sort()

    F = list(range(N))
    R = [0] * N

    def root(x):
        if F[x] == x:
            return x
        else:
            F[x] = root(F[x])
            return F[x]

    def unite(x, y):
        x, y = root(x), root(y)
        if x == y:
            return
        if R[x] < R[y]:
            F[x] = y
        else:
            F[y] = x
            if R[x] == R[y]:
                R[x] += 1

    total = 0
    for c, x, y in E:
        if root(x) != root(y):
            unite(x, y)
            total += c
    print(total)


