        n_choose = Algebra.cumprod(n_choose, p)*self.__ifac%p
      else:
        n_choose = [None]*(r+1); n_choose[0] = 1
        for i in range(r): n_choose[i+1] = n_choose[i]*(n-i)%p
        for i in range(1,r+1): n_choose[i] = n_choose[i]*self.__ifac[i]%p
