    class kruskal():
        def __init__(self, V, E):
            self.V = V
            self.E = E
            self.E.sort(key=lambda x: x[2]) #辺の重みでソート

        def weight(self): #最小全域木の重み和を求める
            UF = UnionFind(len(self.V)) #頂点数でUnion Find Treeを初期化
            res = 0
            for i in range(len(self.E)):
                e = self.E[i]

                if (UF.same(e[0], e[1])) == False:
                    UF.unite(e[0], e[1])
                    res += e[2]

            return res

        def edge(self):
            UF = UnionFind(len(self.V)) #頂点数でUnion Find Treeを初期化
            res_E = []
            for i in range(len(self.E)):
                e = self.E[i]

                if (UF.same(e[0], e[1])) == False:
                    UF.unite(e[0], e[1])
                    res_E.append(e)

            return res_E

