class UnionFindTree():
    def __init__(self, n):
        self.n = n
        self.par = [i for i in range(n)]
        self.siz = [1] * n

    def find(self, x):
        if self.par[x] == x:
            return x
        else:
            self.par[x] = self.find(self.par[x])
            return self.par[x]

    def unite(self, x, y):
        x = self.find(x)
        y = self.find(y)

        if x == y: return False

        if self.siz[x] < self.siz[y]:
            x, y = y, x

        self.siz[x] += self.siz[y]
        self.par[y] = x

    def same(self, x, y):
        return self.find(x) == self.find(y)

    def size(self, x):
        return self.siz[self.find(x)]

