import sys


class UnionFind:
    def __init__(self, n) -> None:
        self.parents = [-1] * n  # direct parent (equals root after calling root on it or its descendants)
        self.sizes = [1] * n  # represents size if it's root
        self.n_groups = n

    def root(self, i: int) -> int:
        if self.parents[i] == -1:
            return i
        else:
            ret = self.root(self.parents[i])
            self.parents[i] = ret
            return ret

    def is_united(self, i: int, j: int):
        return self.root(i) == self.root(j)

    def unite(self, i: int, j: int) -> bool:
        r_i = self.root(i)
        r_j = self.root(j)
        if r_i == r_j:
            return False
        if self.sizes[r_i] < self.sizes[r_j]:
            self.parents[r_i] = r_j
            self.sizes[r_j] += self.sizes[r_i]
        else:
            self.parents[r_j] = r_i
            self.sizes[r_i] += self.sizes[r_j]
        self.n_groups -= 1
        return True


