        self.par = np.full(n+1, -1, np.int64)

    def find(self, x):
        if self.par[x] < 0:
            return x
        else:
            self.par[x] = self.find(self.par[x])
            return self.par[x]

    def union(self, x, y):
        x = self.find(x)
        y = self.find(y)

        if x == y: return

        if abs(self.par[x]) < abs(self.par[y]):
            self.par[y] += self.par[x]
            self.par[x] = y
