def makeCostMap(n, X, Y):
    xCostList = []
    yCostList = []
    for i in range(1, n):
        xCost = abs(X[i][1] - X[i - 1][1])
        yCost = abs(Y[i][1] - Y[i - 1][1])
        xCostList.append([X[i - 1][0], X[i][0], xCost])
        yCostList.append([Y[i - 1][0], Y[i][0], yCost])
    return xCostList, yCostList

class UnionFind():
    parents = []
    count = 0

    def __init__(self, n):
        self.count = n
        self.parents = [i for i in range(n)]

    def find(self, i):
        if self.parents[i] == i:
            return i
        else:
            self.parents[i] = self.find(self.parents[i])
            return self.parents[i]

    def unite(self, i, j):
        root_i = self.find(i)
        root_j = self.find(j)
        if root_i == root_j:
            return
        elif root_i < root_j:
            self.parents[root_j] = root_i
        else:
            self.parents[root_i] = root_j

    def same(self, i, j):
        return self.find(i) == self.find(j)


def findMinCost(n, xCostList, yCostList):
    integratedCostList = xCostList + yCostList
    integratedCostList = sorted(integratedCostList, key=lambda x:x[2])
    totalCost = 0
    uf = UnionFind(n)
    for info in integratedCostList:
        city1, city2, cost = map(int, info)
        if uf.same(city1, city2):
            continue
        uf.unite(city1, city2)
        totalCost += cost
    return totalCost



