def get_keta_plusnum(n,m):
    if n<=m:
        print("error")
    else:
        hit_num=[0 for i in range(n)]
        for keta in range(1,n-m+1):
            for j in range(n+1-keta):
                if j!=n-keta:
                    hit_num[j]+=10**(keta-1)*comb(n-1-keta,m-1)
