def big_array(N: int, K: int, queries: list)->int:
    d = {}
    for a, b in queries:
        d.setdefault(a, 0)
        d[a] += b

    count = 0
    ans = 0
    for k, v in sorted(d.items()):
        count += v
        if K <= count:
            ans = k
            break
    return ans


