def solve(sa, sb, sc):

    isEnd = False
    current = ""
    next = "a"
    while True:
        current = next

        if next == "a":
            sa, next, isEnd = pick(sa)
        elif next == "b":
            sb, next, isEnd = pick(sb)
        else:
            sc, next, isEnd = pick(sc)

        if isEnd:
            return current.upper()

def pick(s):
    if len(s) == 0:
        return "", "", True
    else:
        return s[1:], s[0], False

