import sys


def solve(S_A: str, S_B: str, S_C: str):
    hands = {
        'a': S_A,
        'b': S_B,
        'c': S_C,
    }
    turn = 'a'
    while True:
        if hands[turn] == "":
            print(turn.upper())
            return
        s = hands[turn]
        hands[turn] = s[1:]
        turn = s[0]


