def f(z,A,B,C):
    if z == "a":
        if len(A) == 0:
            return "A"
        else:
            z = A[0]
            A = A[1:]
    elif z == "b":
        if len(B) == 0:
            return "B"
        else:
            z = B[0]
            B = B[1:]
    elif z == "c":
        if len(C) == 0:
            return "C"
        else:
            z = C[0]
            C = C[1:]
    return f(z,A,B,C)
