class Player:

    def __init__(self, name, s):
        self.name = name
        self.cards = list(s)

    @property
    def is_winner(self):
        return len(self.cards) == 0

    def _drop(self):
        dropped = self.cards.pop(0)
        return dropped

    def play(self):
        if len(self.cards) >= 1:
            dropped = self._drop()
            return dropped
        return None

    def __str__(self):
        return self.name

