def judge_cardgame_winner(a_player_cards_str, b_player_cards_str, c_player_cards_str):

    a_players_hand_queue = deque([ s for s in a_player_cards_str ])
    b_players_hand_queue = deque([ s for s in b_player_cards_str ])
    c_players_hand_queue = deque([ s for s in c_player_cards_str ])

    discard = a_players_hand_queue.popleft()

    while a_players_hand_queue!=[] and b_players_hand_queue!=[] and c_players_hand_queue!=[]:
        if discard=='a':
            try:
                discard = a_players_hand_queue.popleft()
            except:
                return 'A'
        if discard=='b':
            try:
                discard = b_players_hand_queue.popleft()
            except:
                return 'B'
        if discard=='c':
            try:
                discard = c_players_hand_queue.popleft()
            except:
                return 'C'


